"""Generate only a clean source-only review form; no evaluator judgments imported."""
import hashlib,html,json
from pathlib import Path
ROOT=Path.cwd(); OUT=ROOT/'docs/expert-review-source-feasibility-20261026'; OUT.mkdir(exist_ok=True)
AUDIT=ROOT/'planning/review-assets/recovery-step8-20261026/form-review';AUDIT.mkdir(exist_ok=True)
source=ROOT/'data/cache/recovery-step8-bounded-sources-20261026/source-qualification.json'
raw=json.loads(source.read_bytes()); esc=html.escape
questions=[
 ('direct_reporting','How directly do these excerpts report this target in relation to this indication?',['Direct reporting across the supplied material','Direct reporting in some excerpts only','Only indirect or ambiguous reporting','No direct reporting identified']),
 ('context','Is the study or biological context sufficiently specified for this limited review?',['Sufficiently specified','Partly specified; important context missing','Insufficiently specified']),
 ('reporting_types','Can you distinguish study aims/methods, reported findings and author interpretation?',['Clearly distinguishable','Partly distinguishable','Not sufficiently distinguishable']),
 ('traceability','Are the article identifiers and passage references usable for tracing statements?',['Usable as supplied','Usable with clarification','Insufficient for tracing']),
 ('uncertainty','What level of uncertainty assessment does the supplied material permit?',['Quantitative and qualitative assessment','Qualitative assessment only','Insufficient information for either']),
 ('sufficiency','Can you answer the limited question: what do these excerpts report, and what remains unknown?',['Yes, within a narrow stated scope','Partly; a useful answer needs explicit gaps','No; material is insufficient']),
 ('missing','What additional information would most improve this review?',['Study or biological context','Results, effect estimates or uncertainty','Target/indication identity or mapping','Article identity, dates or source provenance','No additional information needed for this limited question','Other — describe below'])]
sections=[]; text_list=[]
for ci,c in enumerate(raw['contexts']):
    label='Psoriasis' if c['symbol']=='BTK' else "Crohn’s disease"
    parts=[f'<section id="context-{ci}"><h2>{esc(c["symbol"])} · {label}</h2><p>Target: <code>{esc(c["target_id"])}</code> · Indication: <code>{esc(c["indication_id"])}</code></p><p><strong>Question:</strong> What do the supplied excerpts report about this target and indication, and what remains unknown?</p><p>Intended action, modality and tissue: <strong>unassigned</strong>. Do not infer an intervention recommendation.</p><p>Three article identifiers; four passage occurrences. Repeated or overlapping text may occur. Passage counts are not counts of independent studies.</p><div class="columns"><div><h3>Original supplied excerpts</h3>']
    for si,s in enumerate(c['offered_snippets']):
        record=next(a for a in c['article_records'] if a['article_id']==s['article_id']); m=record['metadata']; ident=f'{c["symbol"]}-P{si+1}'
        text_list.append(s['text'])
        parts.append(f'<article class="passage"><h4>{ident} · PMID {esc(s["article_id"])}</h4><blockquote data-source-index="{len(text_list)-1}">{esc(s["text"])}</blockquote><p class="small">Reported section: {esc(str(s["section"]))}. Raw publicationYear: {esc(str(m["publicationYear"]))}; raw publicationDate: {esc(str(m["publicationDate"]))}. Dates are source metadata, not a verified chronology.</p><details><summary>Original source reference and locator</summary><p>PubMed reference: <code>https://pubmed.ncbi.nlm.nih.gov/{s["article_id"]}/</code></p><pre>{esc(json.dumps({k:s[k] for k in ("source_id","source_sha256","row_group","row","list_index","text_sha256","tStart","tEnd","dStart","dEnd")},indent=2))}</pre></details></article>')
    parts.append('</div><div><h3>Your independent assessment</h3>')
    for qi,(key,prompt,options) in enumerate(questions):
        parts.append(f'<fieldset><legend>{qi+1}. {esc(prompt)}</legend>')
        for oi,option in enumerate(options+['Cannot assess from the supplied material','Outside my expertise']):
            parts.append(f'<label class="choice"><input type="radio" name="{c["symbol"]}_{key}" value="{esc(option,quote=True)}"><span>{esc(option)}</span></label>')
        parts.append('</fieldset>')
    parts.append(f'<label>Evidence, rationale or missing information (optional)<textarea name="{c["symbol"]}_rationale" rows="4" placeholder="Use passage labels, e.g. {c["symbol"]}-P1"></textarea></label><label>Confidence (optional)<select name="{c["symbol"]}_confidence"><option value="">Not recorded</option><option>Low</option><option>Moderate</option><option>High</option></select></label></div></div></section>')
    sections.append(''.join(parts))
metadata={'schema_version':1,'instrument_id':'source-feasibility-20261026-v1','role':'evaluation_only','status':'unadjudicated','review_type':'source_only','source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'contexts':[{'symbol':c['symbol'],'target_id':c['target_id'],'indication_id':c['indication_id'],'action':None,'modality':None,'tissue':None,'passages':[{'label':f'{c["symbol"]}-P{i+1}','article_id':s['article_id'],'text_sha256':s['text_sha256']} for i,s in enumerate(c['offered_snippets'])]} for c in raw['contexts']]}
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>Source feasibility review · BTK and CTLA4</title><style>
*{box-sizing:border-box}body{font-family:system-ui,Segoe UI,sans-serif;line-height:1.55;margin:0;background:#f3f6f8;color:#183045}header,main,footer{max-width:1400px;margin:auto;padding:24px}h1{line-height:1.2}h2{margin-top:0}section{background:white;border:1px solid #ccd7e0;border-radius:10px;padding:22px;margin:0 0 24px}.notice{padding:16px;border-left:4px solid #a77b20;background:#fff5da}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px}.passage,fieldset{border:1px solid #ccd7e0;border-radius:6px;padding:16px;margin:0 0 16px;min-width:0}blockquote{white-space:pre-wrap;margin:0;overflow-wrap:anywhere}.choice{display:flex;gap:10px;margin:8px 0;align-items:flex-start}input[type=radio]{margin-top:6px;flex-shrink:0}legend{font-weight:650}label{display:block}textarea,input:not([type=radio]),select{width:100%;padding:10px;font:inherit;margin:6px 0 16px;border:1px solid #93a8b7;border-radius:4px}pre,code{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}.small{font-size:.88rem;color:#435e70}button{font:inherit;background:#17526e;color:white;padding:12px 20px;border:0;border-radius:5px;cursor:pointer}summary{cursor:pointer}a{color:#17526e}:focus-visible{outline:3px solid #b88622;outline-offset:3px}@media(max-width:850px){.columns{grid-template-columns:1fr}header,main,footer{padding:14px}section{padding:14px}}@media print{body{background:white}.columns{display:block}button{display:none}fieldset,.passage{break-inside:avoid}}
</style></head><body><header><h1>Source feasibility review</h1><p>BTK / psoriasis and CTLA4 / Crohn’s disease</p><p class="notice">Please complete this source-only reference before seeing any candidate response or AI assessment. This is not a professional examination. There is no answer key, score or preselected response. The two contexts are not certified fresh cases, and this form is not completed expert review.</p><p>Use only the supplied excerpts. Internet access is not required. Original wording, repeated text and literal HTML are preserved. This AI-prepared instrument has not itself been scientifically adjudicated.</p><p><a href="#context-0">BTK sources and questions</a> · <a href="#context-1">CTLA4 sources and questions</a> · <a href="#export">Export answers</a></p></header><main><form id="review"><section><h2>Your review</h2><label>Reviewer ID (optional; use an assigned ID rather than contact information)<input name="reviewer_id"></label><label>Relevant expertise (optional)<input name="expertise"></label><label>Conflicts of interest (optional; describe or write none)<textarea name="conflicts" rows="2"></textarea></label><label>Prior exposure to these sources, questions or candidate responses (optional)<textarea name="prior_exposure" rows="2"></textarea></label><label>Review sequence (optional)<select name="review_sequence"><option value="">Not recorded</option><option>Source-only review before candidate exposure</option><option>Previously saw a candidate or AI assessment</option><option>Uncertain</option></select></label><label>Elapsed review minutes (optional)<input name="elapsed_minutes" type="number" min="0" step="0.1"></label></section>'''+''.join(sections)+'''<section id="export"><h2>Save your answers</h2><p>Unanswered items remain null. Export does not grade answers or establish scientific validation. Nothing is sent over the network. This page does not automatically save drafts; export before closing, and return the JSON to your coordinator through the agreed channel.</p><button type="button" id="download">Export review JSON</button><p id="status" role="status" aria-live="polite"></p></section></form></main><footer>Source-only development feasibility · Evaluation-only · No intervention recommendation</footer><script>
const instrument='''+json.dumps(metadata,ensure_ascii=True)+''';
function buildExport(){const f=new FormData(document.getElementById('review')); const names=[...new Set([...document.querySelectorAll('[name]')].map(x=>x.name))];const answers={};for(const name of names){const value=f.get(name);answers[name]=typeof value==='string'&&value.trim()!==''?value:null;}return {...instrument,exported_at:new Date().toISOString(),answers};}
document.getElementById('download').addEventListener('click',()=>{const data=buildExport();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='source-feasibility-review-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent='Review exported locally. Unanswered items remain null.';});
</script></body></html>'''
(OUT/'Expert-source-review.html').write_text(page,encoding='utf-8')
(OUT/'README.md').write_text('''# Source-only feasibility review

Open `Expert-source-review.html` in a browser. It works offline. Read each source excerpt and answer seven short items for each of two contexts. All answers are optional; cannot-assess and outside-expertise choices are available. No score or pass/fail outcome is assigned.

Complete this reference before viewing candidate responses or AI assessments. Record prior exposure honestly. The material has six article identifiers and eight passage occurrences; repeated text is retained and does not represent another independent study. Action, modality and tissue are unassigned.

Export the review JSON before closing. Drafts are not automatically saved. Return it through your coordinator's agreed channel; the form sends nothing. Exported answers are evaluation-only and unadjudicated. Blank forms are not human responses, and these contexts are not certified fresh cases.

Source references and dates reproduce supplied metadata; no external lookup is needed. Preserve literal source wording in your assessment. Report important missing information rather than assuming it.
''',encoding='utf-8')
(OUT/'Recruitment.md').write_text('''# Invitation: source-only evidence feasibility review

We invite reviewers with relevant immunology, psoriasis/IBD, genetics or evidence-appraisal expertise to assess whether a small set of supplied excerpts supports a limited target–disease reporting question. The two contexts are BTK/psoriasis and CTLA4/Crohn's disease. You may select outside my expertise for either context or item.

The offline form contains eight passage occurrences from six article identifiers and seven multiple-choice items per context. Please record your actual review time; no duration or professional performance threshold is imposed. Optional comments, confidence, expertise, conflicts and prior exposure help interpret your feedback.

Please complete the source-only reference independently before receiving candidate responses, AI assessments or another reviewer's answers. No external research is required. Return the exported JSON via the coordinator's agreed channel. Scheduling and any compensation are arranged directly with the coordinator.

This is development feasibility work, not clinical guidance or a validated benchmark. A completed form contributes a source-only judgment; it does not by itself complete reviewer coverage or adjudication.
''',encoding='utf-8')
provenance={'schema_version':1,'role':'evaluation_only','source_path':str(source),'source_sha256':metadata['source_sha256'],'clean_files':[p.name for p in OUT.iterdir() if p.is_file()],'passage_count':len(text_list),'question_count':14,'no_answer_key':True,'no_candidate_outputs':True,'browser_qa':'pending_root','share_zip':'not_created_pending_browser_qa','files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.iterdir() if p.is_file()}}
(AUDIT/'provenance.json').write_text(json.dumps(provenance,indent=2),encoding='utf-8')
(AUDIT/'expected-text.json').write_text(json.dumps(text_list,ensure_ascii=True),encoding='utf-8')
print(json.dumps(provenance,indent=2))
